-- =====================================================================
-- EVENT PASS - ready-to-use queries
-- Run in Supabase SQL Editor, or call the same operations from db.py.
-- Replace the values in 'QUOTES' before running.
-- =====================================================================

-- 1) GET the event for the public page
select name, tagline, description,
       event_date as date, start_time as time, venue, organizer
from public.events
limit 1;

-- 2) INSERT a registration (token is generated by the backend, e.g. secrets.token_urlsafe(18))
insert into public.registrations (token, name, usn, branch, phone, email)
values ('RANDOM_QR_TOKEN_HERE', 'Aarav Sharma', 'CSE001', 'CSE', '9876543210', 'aarav@example.com')
returning id, name, usn, branch, status, registered_at;   -- token is never returned

-- 3) CHECK duplicates before registering
select id, 'email' as matched_on from public.registrations where email = 'aarav@example.com'
union all
select id, 'phone' from public.registrations where phone = '9876543210';

-- 4) LOOK UP a scanned QR token (service_role only - anon cannot read tokens)
select id, name, usn, branch, status, verified_at
from public.registrations
where token = 'RANDOM_QR_TOKEN_HERE';

-- 5) CHECK IN / VERIFY a pass (atomic: only a 'pending' pass can be verified)
--    If 0 rows are returned, query 4 tells you if it is 'duplicate', 'revoked' or 'invalid'.
update public.registrations
   set status = 'verified', verified_at = now()
 where token = 'RANDOM_QR_TOKEN_HERE'
   and status = 'pending'
returning id, name, status, verified_at;

-- 6) DASHBOARD stats
select count(*) as total,
       count(*) filter (where status = 'verified') as verified,
       count(*) filter (where status = 'pending')  as pending,
       count(*) filter (where status = 'revoked')  as revoked
from public.registrations;

-- 7) LIST all participants, newest first (no token)
select id, name, usn, branch, phone, email, status, registered_at, verified_at
from public.registrations
order by registered_at desc;

-- 8) MARK attendance manually / undo
update public.registrations
   set status = 'verified', verified_at = now()
 where id = 'EP-0001'
returning id, name, status, verified_at;

update public.registrations
   set status = 'pending', verified_at = null
 where id = 'EP-0001';

-- 9) REVOKE a pass / RESTORE it
update public.registrations set status = 'revoked' where id = 'EP-0001';
update public.registrations
   set status = 'pending', verified_at = null
 where id = 'EP-0001' and status = 'revoked';

-- 10) DELETE a registration permanently (IDs are not reused)
delete from public.registrations where id = 'EP-0001';

-- 11) UPDATE the event details (admin)
update public.events
   set name = 'TechNova 2026',
       tagline = 'Innovate. Build. Celebrate.',
       description = 'Annual tech fest.',
       event_date = date '2026-12-18',
       start_time = time '09:30',
       venue = 'Main Auditorium, College Campus',
       organizer = 'Student Council'
 where id = (select id from public.events limit 1)
returning *;

-- 12) EXPORT participants as CSV-friendly rows
select id as "Registration ID", name, usn as "USN", branch, phone, email,
       registered_at as "Registered At", status, verified_at as "Verified At"
from public.registrations
order by registered_at;
